const payload = msg.payload;
const knownSensors = [{
        location: '1_Sayfield_Cottages/garden',
        category: 'meteo',
        model: 'LaCrosse-TX29IT',
        id: 46,
        send_every_sec: 60,
        average_fields: ["temperature_C", "humidity"]
    }, {
        location: '1_Sayfield_Cottages',
        category: 'electricity_usage',
        model: 'CurrentCost-TX',
        id: 77,
        send_every_sec: 60,
        average_fields: ["power0_W", "power1_W", "power2_W"]
    }
];

const knownSensor =
    knownSensors.find(
        sensor =>
            sensor.model == payload.model &&
            sensor.id == payload.id);
const isFrequencyHopping = !!payload['center_frequency'];

if (!!knownSensor) {
    msg.telemetryType = 'EXISTING_SENSOR';
    msg.payload.location = knownSensor.location;
    msg.payload.category = knownSensor.category;
    msg.payload.send_every_sec = knownSensor.send_every_sec;
    msg.payload.average_fields = [...knownSensor.average_fields];
}
else if (isFrequencyHopping) {
    msg.telemetryType = 'FREQUENCY_HOPPING'
}
else {
    msg.payload.location = '1_Sayfield_Cottages';
    msg.payload.category = 'unrecognised';
    msg.telemetryType = 'UNRECOGNISED';
}

return msg;

function diff_seconds(dt2, dt1) {
    var diff = (dt2.getTime() - dt1.getTime()) / 1000;

    return Math.abs(Math.round(diff));
}

const reading = msg.payload;

// if no rate limit just send it as is
if (reading.send_every_sec === undefined) {
    return msg;
}

// initialise cache
const cache = flow.get('cache') || {};
const sensorId = `${reading.model}_${reading.id}`;

cache[sensorId] = cache[sensorId] || [];

// If buffer is empty just add current to the array and quit
if (!cache[sensorId].length) {
    const readingToCache = { ...reading };
    readingToCache.average_fields = [...reading.average_fields];

    if (!readingToCache.average_fields) {
        node.warn('NO AVERAGE FIELDS');

        node.warn(msg.payload);
    }

    cache[sensorId].push(readingToCache);
    flow.set('cache', cache);

    node.warn(cache);

    return null;
}

// check incoming reading difference with the first item in the array
const firstItem = cache[sensorId][0];
const differenceThreshold = reading.send_every_sec;
const differenceInSeconds =
    diff_seconds(new Date(reading.time), new Date(firstItem.time));

// If below send_every_sec value than add to the array and send null
if (differenceInSeconds < differenceThreshold) {
    const readingToCache = { ...reading };
    readingToCache.average_fields = [...reading.average_fields];

    if (!readingToCache.average_fields) {
        node.warn('NO AVERAGE FIELDS');

        node.warn(msg.payload);
    }

    cache[sensorId].push(readingToCache);
    flow.set('cache', cache);

    node.warn(cache);

    return null;
}

// otherwise create a reading with average from items in the array
const readingsLength = cache[sensorId].length;
const averageReading = {
    ...cache[sensorId][readingsLength - 1]
}

if (!averageReading.average_fields) {
    node.warn(averageReading);
}

averageReading.average_fields.forEach(field => {
    let fieldSum = cache[sensorId].reduce((acc, curr) => {
        return acc + curr[field];
    }, 0);
    const fieldAverage = fieldSum / readingsLength;

    averageReading[field] = Math.round(fieldAverage * 10) / 10;
});

// clear the array
cache[sensorId] = [];

// add current reading to the array
const readingToCache = { ...reading };
readingToCache.average_fields = [...reading.average_fields];

cache[sensorId].push(readingToCache);

// send the previously created average reading on.
msg.payload = averageReading;

return msg;

const reading = { ...msg.payload };

reading.send_every_sec = undefined;
reading.average_fields = undefined;

msg.payload = reading;

return msg;

let devices = flow.get("devices");

devices = devices || [];

let found = devices.find(device => device.topic == msg.topic);

if (!!found) {
    found.payload = msg.payload;
} else {
    devices.push({ topic: msg.topic, payload: msg.payload });
}

flow.set("devices", devices);

return msg;

const devices = flow.get("devices");

devices.sort((a, b) => {
    if((!a && !a[0]) || (!b && !b[0])) {
        return 0;
    }

    const payloadA = a.payload || a[0].payload;
    const payloadB = b.payload || b[0].payload;

    const timeA = payloadA.time;
    const timeB = payloadB.time;

    if (timeA < timeB) {
        return -1;
    }

    if (timeA > timeB) {
        return 1;
    }

    return 0;
});

