function getPayloadTime(device) {
    if (!device) {
        return undefined;
    }

    const payload = device.payload || device[0].payload;

    return payload.time;
}

function getPayload(device) {
    if (!device) {
        return undefined;
    }

    const payload = device.payload || device[0].payload;

    return payload;
}

