let meters = flow.get('meters') || [];
let found = meters.find(t =>
    t.id == msg.payload.id && t.model == msg.payload.model);

if (!!found) {
    const now = new Date().toISOString();
    const needsAvg = checkNeedsAvg(found.lastLogged, now);

    if (found.avg_power_W && !needsAvg) {
        const metersQueue = flow.get('metersQueue') || [];

        metersQueue.push(JSON.parse(JSON.stringify(found)));
        flow.set('metersQueue', metersQueue);
    }

    found.avg_power_W = needsAvg && found.avg_power_W
        ? Math.ceil((found.avg_power_W + msg.payload.power_W) / 2)
        : msg.payload.power_W;
    found.lastLogged = now;
    found.payload = msg.payload;
    found.totalHits++;
} else {
    found = {
        id: msg.payload.id,
        model: msg.payload.model,
        room: msg.payload.room,
        lastLogged: new Date().toISOString(),
        totalHits: 1,
        avg_power_W: msg.payload.power_W,
        payload: msg.payload
    }

    meters.push(found);
}

flow.set('meters', meters);

return msg;

function checkNeedsAvg(lastLogged, now) {
    const lastDate = new Date(lastLogged);
    const nowDate = new Date(now);

    if (lastDate.getDate() == nowDate.getDate()) {
        if (lastDate.getHours() == nowDate.getHours()) {
            return lastDate.getMinutes() == nowDate.getMinutes();
        }
    }

    return false;
}

